//###########################################################
onSortColumnClick = function(evnt) {
  var key;
  key = evnt.target.getAttribute("data-sort-key");
  log(`onSortColumnClick: ${key}`);
  if (sortColumn === key) {
    sortAscending = !sortAscending; // Toggle direction
  } else {
    sortColumn = key;
    sortAscending = false; // New column: start descending
  }
  renderBacktestingTable();
};

sortYearlyResults = function(results) {
  var compareFn, sorted;
  sorted = [...results]; // Copy to avoid mutating original
  compareFn = (function() {
    switch (sortColumn) {
      case "startDate":
        return function(a, b) {
          return a.year - b.year;
        };
      case "profit":
        if (currentIsShort) {
          return function(a, b) {
            return (-a.changeP) - (-b.changeP); // Flipped for Short
          };
        } else {
          return function(a, b) {
            return a.changeP - b.changeP;
          };
        }
        break;
      case "profitA":
        if (currentIsShort) {
          return function(a, b) {
            return (-a.startAr * a.changeP) - (-b.startAr * b.changeP);
          };
        } else {
          return function(a, b) {
            return (a.startAr * a.changeP) - (b.startAr * b.changeP);
          };
        }
        break;
      case "maxRise":
        return function(a, b) {
          return a.maxRiseP - b.maxRiseP;
        };
      case "maxRiseA":
        return function(a, b) {
          return (a.startAr * a.maxRiseP) - (b.startAr * b.maxRiseP);
        };
      case "maxDrop":
        return function(a, b) {
          return (-a.maxDropP) - (-b.maxDropP); // Flipped for max Drops
        };
      case "maxDropA":
        return function(a, b) {
          return (-a.startAr * a.maxDropP) - (-b.startAr * b.maxDropP);
        };
      default:
        return function(a, b) {
          return 0;
        };
    }
  })();
  sorted.sort(compareFn);
  if (!sortAscending) {
    sorted.reverse();
  }
  return sorted;
};

//###########################################################
formatPercent = function(value) {
  var sign;
  sign = value >= 0 ? "+" : "";
  return `${sign}${value.toFixed(1)}%`;
};

formatAbsoluteDelta = function(value, missingSF) {
  var html, sign;
  sign = value >= 0 ? "+" : "";
  html = formatAbsolutePrice(value, missingSF);
  return `${sign}${html}`;
};

formatAbsolutePrice = function(value, missingSF) {
  if (missingSF > 1) {
    return `${value.toFixed(2)}<span class='missing-factor' title='Fehlender Faktor zum exakten historischen Wert.'>${missingSF.toFixed(2)}</span>`;
  } else {
    return `${value.toFixed(2)}`;
  }
};

formatDate = function(value) {
  var date, day, dayStr, month, monthStr, year;
  date = new Date(value);
  day = date.getDate();
  month = date.getMonth() + 1;
  year = date.getFullYear();
  dayStr = day < 10 ? `0${day}` : `${day}`;
  monthStr = month < 10 ? `0${month}` : `${month}`;
  return `${dayStr}.${monthStr}.${year}`;
};

